192|export interface SceneView {
193|  sceneId: string;
194|  ch: number;
195|  chapterTitle: string;
196|  title: string;
197|  emotion: ReaderScene["emotion"];
198|  pages: SubPage[];
199|  prevSceneId: string | null;
200|  nextSceneId: string | null;
201|  k: number;
202|  n: number;
203|}
204|
205|// The only text a scene route ships: this scene, its chapter, its pages,
206|// and neighbor ids for the pager. Throws on unknown scene id.
207|export function buildSceneView(
208|  model: ReaderModel,
209|  sceneId: string,
210|  budgetWords: number = PAGE_WORD_BUDGET,
211|): SceneView {
212|  const flat = model.chapters.flatMap((c) => c.scenes.map((s) => ({ ch: c.ch, chapterTitle: c.title, scene: s })));
213|  const at = flat.findIndex((e) => e.scene.id === sceneId);
214|  if (at < 0 || !flat[at]) throw new Error(`unknown scene ${sceneId}`);
215|  const entry = flat[at] as { ch: number; chapterTitle: string; scene: ReaderScene };
216|  const chapterScenes = flat.filter((e) => e.ch === entry.ch);
217|  const prev = at > 0 ? flat[at - 1] : null;
218|  const next = at < flat.length - 1 ? flat[at + 1] : null;
219|  return {
220|    sceneId,
221|    ch: entry.ch,
222|    chapterTitle: entry.chapterTitle,
223|    title: entry.scene.title,
224|    emotion: entry.scene.emotion,
225|    pages: paginateScene(entry.scene.paragraphs, budgetWords, entry.chapterTitle),
226|    prevSceneId: prev?.scene.id ?? null,
227|    nextSceneId: next?.scene.id ?? null,
228|    k: chapterScenes.findIndex((e) => e.scene.id === sceneId) + 1,
229|    n: chapterScenes.length,
230|  };
231|}
