233|export interface NavState {
234|  sceneId: string;
235|  page: number;
236|}
237|
238|export type NavAction =
239|  | { kind: "next" }
240|  | { kind: "prev" }
241|  | { kind: "goto"; sceneId: string; atEnd?: boolean };
242|
243|export interface NavIndex {
244|  order: string[];
245|  pageCounts: Map<string, number>;
246|}
247|
248|export function buildNavIndex(views: { sceneId: string; pages: number }[]): NavIndex {
249|  return {
250|    order: views.map((v) => v.sceneId),
251|    pageCounts: new Map(views.map((v) => [v.sceneId, v.pages] as [string, number])),
252|  };
