255|// Every pager move in one place: next/prev cross scenes and chapters,
256|// going back lands on the last sub-page, bounds are no-ops, unknown
257|// goto ids keep state.
258|export function navReducer(state: NavState, action: NavAction, index: NavIndex): NavState {
259|  const at = index.order.indexOf(state.sceneId);
260|  if (at < 0) return state;
261|  const pages = index.pageCounts.get(state.sceneId) ?? 1;
262|  if (action.kind === "next") {
263|    if (state.page < pages - 1) return { ...state, page: state.page + 1 };
264|    const nextId = index.order[at + 1];
265|    return nextId === undefined ? state : { sceneId: nextId, page: 0 };
266|  }
267|  if (action.kind === "prev") {
268|    if (state.page > 0) return { ...state, page: state.page - 1 };
269|    const prevId = at > 0 ? index.order[at - 1] : undefined;
270|    if (prevId === undefined) return state;
271|    return { sceneId: prevId, page: (index.pageCounts.get(prevId) ?? 1) - 1 };
272|  }
273|  if (index.order.indexOf(action.sceneId) < 0) return state;
274|  const count = index.pageCounts.get(action.sceneId) ?? 1;
275|  return { sceneId: action.sceneId, page: action.atEnd ? count - 1 : 0 };
276|}
277|
278|// True only when the scene id changed. The container gates observeScene
279|// on this, so sub-page moves never touch the scheduler.
280|export function isSceneEntry(prevSceneId: string | null, nextSceneId: string): boolean {
281|  return prevSceneId !== nextSceneId;
282|}
283|
284|export interface SceneEntryGate {
285|  observedId: string | null;
286|  routeId: string | null;
287|  manifestReady: boolean;
288|}
289|
290|// The container's effect gate in one testable place: observe exactly once
291|// per route id, only after the manifest lands. Route params can lag a
292|// render, so the last observed id is compared before every observe call.
293|export function nextSceneEntry(gate: SceneEntryGate): {
294|  shouldObserve: boolean;
295|  nextObservedId: string | null;
296|} {
297|  if (!gate.routeId || !gate.manifestReady || !isSceneEntry(gate.observedId, gate.routeId)) {
298|    return { shouldObserve: false, nextObservedId: gate.observedId };
299|  }
300|  return { shouldObserve: true, nextObservedId: gate.routeId };
301|}
302|
303|// Throws on unordered scenes and on paragraphs covered zero or two times.
304|export function buildReaderModel(
305|  book: Pick<Book, "id" | "title" | "author" | "chapters" | "paragraphs" | "textVersion">,
306|  analysis: { scenes: AnalyzedScene[] },
307|): ReaderModel {
308|  const byN = new Map(book.paragraphs.map((p) => [p.n, p]));
309|  const scenes = [...analysis.scenes];
310|  for (let i = 1; i < scenes.length; i++) {
311|    const prev = scenes[i - 1];
312|    const cur = scenes[i];
313|    if (prev && cur && (cur.start_n < prev.start_n || (cur.start_n === prev.start_n && cur.end_n < prev.end_n))) {
314|      throw new Error(`scenes out of order at ${cur.id}`);
315|    }
316|  }
317|  const seen = new Set<number>();
318|  const sceneParagraphs = new Map<string, ReaderParagraph[]>();
319|  for (const scene of scenes) {
320|    const paras: ReaderParagraph[] = [];
321|    for (let n = scene.start_n; n <= scene.end_n; n++) {
322|      const p = byN.get(n);
323|      if (!p) throw new Error(`scene ${scene.id} covers missing ordinal ${n}`);
324|      if (seen.has(n)) throw new Error(`ordinal ${n} covered twice`);
325|      seen.add(n);
326|      paras.push({ id: p.id, n: p.n, text: p.text });
327|    }
328|    sceneParagraphs.set(scene.id, paras);
329|  }
330|  if (seen.size !== book.paragraphs.length) {
331|    throw new Error(`coverage gap: ${book.paragraphs.length - seen.size} paragraphs uncovered`);
332|  }
333|  const chapters: ReaderChapter[] = book.chapters.map((chapter) => {
334|    const mine = scenes.filter((s) => s.ch === chapter.ch);
335|    if (mine.some((s) => s.start_n < chapter.start_n || s.end_n > chapter.end_n)) {
336|      throw new Error(`a scene crosses chapter ${chapter.ch} bounds`);
337|    }
338|    return {
339|      ch: chapter.ch,
340|      title: chapter.title,
341|      scenes: mine.map((s) => ({
342|        id: s.id,
343|        title: s.title,
344|        emotion: s.final === null ? null : { ...s.final },
345|        paragraphs: sceneParagraphs.get(s.id) ?? [],
346|      })),
347|    };
348|  });
349|  return {
350|    bookId: book.id,
351|    textVersion: book.textVersion,
352|    title: book.title,
353|    author: book.author,
354|    chapters,
355|  };
