255|// Every pager move in one place: next/prev cross scenes and chapters,
256|// going back lands on the last sub-page, bounds are no-ops, unknown
257|// goto ids keep state.
258|export function navReducer(state: NavState, action: NavAction, index: NavIndex): NavState {
259|  const at = index.order.indexOf(state.sceneId);
260|  if (at < 0) return state;
261|  const pages = index.pageCounts.get(state.sceneId) ?? 1;
262|  if (action.kind === "next") {
263|    if (state.page < pages - 1) return { ...state, page: state.page + 1 };
264|    const nextId = index.order[at + 1];
265|    return nextId === undefined ? state : { sceneId: nextId, page: 0 };
266|  }
267|  if (action.kind === "prev") {
268|    if (state.page > 0) return { ...state, page: state.page - 1 };
269|    const prevId = at > 0 ? index.order[at - 1] : undefined;
270|    if (prevId === undefined) return state;
271|    return { sceneId: prevId, page: (index.pageCounts.get(prevId) ?? 1) - 1 };
272|  }
273|  if (index.order.indexOf(action.sceneId) < 0) return state;
274|  const count = index.pageCounts.get(action.sceneId) ?? 1;
275|  return { sceneId: action.sceneId, page: action.atEnd ? count - 1 : 0 };
