1|"use client";
2|
3|import { useCallback, useEffect, useMemo, useRef, useState } from "react";
4|import { useParams, useRouter } from "next/navigation";
5|import { parseManifest, styleHasTracks } from "@/core/music";
6|import type { MusicManifest, PersistedMusicPrefs, SceneSignal } from "@/core/music";
7|import { EMOTIONS } from "@/core/types";
8|import { dispatch, findChopinPlaylist, startSession } from "@/core/music-session";
9|import type { MusicIntent, MusicSession, SessionView } from "@/core/music-session";
10|import { nextSceneEntry } from "@/core/reader";
11|import { DEFAULT_VOLUME, loadMusicPrefs, saveMusicPrefs } from "./music-prefs";
12|import { Player } from "./player";
13|import { THEME_KEY, TopLine } from "./folio/chrome";
14|import { DevPanel } from "./folio/dev-panel";
15|
16|export interface SlimScene {
17|  id: string;
18|  ch: number;
19|  emotion: SceneSignal | null;
20|}
21|
22|export interface ChapterJump {
23|  ch: number;
24|  title: string;
25|  firstSceneId: string;
26|}
27|
28|const DEV_LABELS: Record<(typeof EMOTIONS)[number], string> = {
29|  calma: "calm",
30|  alegria: "joy",
31|  tristeza: "sadness",
32|  suspenso: "suspense",
33|  misterio: "mystery",
34|  aventura: "adventure",
35|  combate: "combat",
36|  asombro: "wonder",
37|};
38|
39|// Client container: bridges the music session to React state. It cues
40|// music on scene entry only, from the route id. Sub-page moves never
41|// reach the session. Params can lag a render, so the last observed id
42|// is compared before every scene entry.
43|export function Reader({
44|  scenes,
45|  chapters,
46|  bookTitle,
47|  bookAuthor,
48|  children,
49|}: {
50|  scenes: SlimScene[];
51|  chapters: ChapterJump[];
52|  bookTitle: string;
53|  bookAuthor: string;
54|  children: React.ReactNode;
55|}) {
56|  const routeParams = useParams();
57|  const router = useRouter();
58|  const param = routeParams?.sceneId;
59|  const routeSceneId = typeof param === "string" ? param : null;
60|  const [manifest, setManifest] = useState<MusicManifest | null>(null);
61|  const [view, setView] = useState<SessionView | null>(null);
62|  const [musicFailed, setMusicFailed] = useState(false);
63|  // Volume and mute persist next to the style in one prefs object; the
64|  // player stays a controlled view over them. State starts at the server
65|  // defaults so hydration matches, then a mount effect applies stored
66|  // prefs (parsed once) to volume, muted, and style via prefsRef.
67|  const [volume, setVolume] = useState(DEFAULT_VOLUME);
68|  const [muted, setMuted] = useState(false);
69|  const [theme, setTheme] = useState<"light" | "dark">("light");
70|  const [devOpen, setDevOpen] = useState(false);
71|  const prefsRef = useRef<PersistedMusicPrefs | null>(null);
72|  // Ref mirrors so send and persist handlers always read fresh values.
73|  const volumeRef = useRef(volume);
74|  volumeRef.current = volume;
75|  const mutedRef = useRef(muted);
76|  mutedRef.current = muted;
77|  const byId = useMemo(() => new Map(scenes.map((s) => [s.id, s.emotion])), [scenes]);
78|  const byIdRef = useRef(byId);
79|  byIdRef.current = byId;
80|  const manifestRef = useRef(manifest);
81|  manifestRef.current = manifest;
82|  const routeRef = useRef(routeSceneId);
83|  routeRef.current = routeSceneId;
84|  const sessionRef = useRef<MusicSession | null>(null);
85|  const observedRef = useRef<string | null>(null);
86|
87|  // The one bridge into the session: builds the context (clock, rng,
88|  // scene signals) and mirrors the view and a style change to state.
89|  const send = useCallback((intent: MusicIntent) => {
90|    const session = sessionRef.current;
91|    const fetched = manifestRef.current;
92|    if (!session || !fetched) return;
93|    const next = dispatch(session, intent, {
94|      manifest: fetched,
95|      signalOf: (sceneId) => byIdRef.current.get(sceneId) ?? null,
96|      routeSceneId: routeRef.current,
97|      nowSec: Date.now() / 1000,
98|      rng: Math.random,
99|    });
100|    sessionRef.current = next;
101|    if (next.view !== session.view) setView(next.view);
102|    if (next.selection !== session.selection) {
103|      saveMusicPrefs({
104|        style: next.selection.style,
105|        volume: volumeRef.current,
106|        muted: mutedRef.current,
107|      });
108|    }
109|  }, []);
110|
111|  // Stored prefs load once here, after the server-matching first render.
112|  // Saves happen only on user actions below, so the defaults above never
113|  // overwrite storage before this runs. The fetch below resolves later and
114|  // reads the style through the ref.
115|  useEffect(() => {
116|    const prefs = loadMusicPrefs();
117|    prefsRef.current = prefs;
118|    if (prefs !== null) {
119|      if (prefs.volume !== null) setVolume(prefs.volume);
120|      setMuted(prefs.muted);
121|    }
122|    try {
123|      const stored = window.localStorage.getItem(THEME_KEY);
124|      if (stored === "light" || stored === "dark") {
125|        setTheme(stored);
126|      } else {
127|        setTheme(document.documentElement.getAttribute("data-theme") === "dark" ? "dark" : "light");
128|      }
129|    } catch {
130|      // The inline script already set a theme; keep the default.
131|    }
132|    if (new URLSearchParams(window.location.search).has("dev")) setDevOpen(true);
133|  }, []);
134|
135|  useEffect(() => {
136|    let cancelled = false;
137|    fetch("/music/manifest.json")
138|      .then((res) => {
139|        if (!res.ok) throw new Error(`manifest ${res.status}`);
140|        return res.json();
141|      })
142|      .then((json: unknown) => {
143|        if (cancelled) return;
144|        const parsed = parseManifest(json);
145|        setManifest(parsed);
146|        const session = startSession(parsed, prefsRef.current);
147|        sessionRef.current = session;
148|        setView(session.view);
149|      })
150|      .catch(() => {
151|        if (!cancelled) setMusicFailed(true);
152|      });
153|    return () => {
154|      cancelled = true;
155|    };
